TIPOS_PADROES = {
    "Admissao": "admissao",
    "Retorno": "retorno",
    "Intercorrencia": "intercorrencia",
    "Exame": "exame",
    "Consulta": "consulta",
}


def extrair_data(texto):
    match = re.match(r"(\d{2}/\d{2}/\d{4})", texto)
    return match.group(1) if match else ""


def extrair_tipo_evento(texto):
    for palavra, tipo in TIPOS_PADROES.items():
        padrao = rf"\d{{2}}/\d{{2}}/\d{{4}} - {palavra}"
        if re.search(padrao, texto):
            return tipo
    return "consulta"


def gerar_evolucoes():
    registros = []
    for i, texto in enumerate(EVOLUCOES_PACIENTE, start=1):
        registros.append({
            "id": i,
            "data": extrair_data(texto),
            "tipo_evento": extrair_tipo_evento(texto),
            "texto_bruto": texto,
        })
    return registros
